INSERT INTO `facebook_post_config` (`id`, `type`, `message`, `schedule`, `active`) VALUES
(1, 'results', '    ✨ 📊 Daily Unemployment Report – ${date}\n    Here’s today’s summary of unemployment data collected across Pagadian City:\n\n    ${barangay}\n\n\n    This real-time data helps us monitor employment trends and develop targeted support programs.\n    Stay informed and be part of the solution. 💼📍\n\n    #PagadianCity #UMSRT #UnemploymentUpdate #BarangayStats #RealTimeMonitoring', '10:00:00', 0),
(2, 'form', '✍️ Are you currently unemployed? Let your voice be counted!\r\n\r\nThe Pagadian City Unemployment Monitoring System is now accepting submissions.\r\n\r\n📍 By filling out this form, you help us:\r\n\r\nIdentify which barangays need support\r\n\r\nDevelop targeted livelihood programs\r\n\r\nBring job opportunities closer to where they’re needed most\r\n\r\n📌 It only takes 2 minutes. Your data makes a difference!\r\n\r\n👉 Submit your info here: [Insert Form Link]\r\n\r\nAll submissions are secure, confidential, and used to improve local services.\r\n\r\nLet\'s work together for a more empowered, employed Pagadian City. 💼📊\r\n\r\n#PagadianCity #UMSRT #UnemploymentSupport #SignUpNow #JobReadyP', '08:00:00', 0);
